SELECT d.PERIODDATE AS `报告期`, d.A_STOCKCODE AS `股票代码`, d.A_STOCKSNAME AS `股票简称`, d.CASH_BT AS `每10股派现(含税)` FROM STK_DIV_INFO d JOIN GET_A_SEC_CODE s ON d.COMCODE = s.COMCODE AND s.ISVALID = 1 WHERE d.ISVALID = 1 AND s.SEC_SNAME LIKE '%中国神华%' AND d.PERIODDATE >= '2023-01-01' AND d.PERIODDATE <= '2023-12-31' ORDER BY d.PERIODDATE DESC, d.PRG_CODE DESC LIMIT 10;
